# Telnet command constants
IAC = 0xFF
SB = 0xFA
SE = 0xF0
LINEMODE = 32
SLC = 1

# SLC function codes (from RFC 1184)
SLC_EOF = 1
SLC_EW = 2
SLC_BRK = 3
SLC_IP = 4
SLC_AO = 5
SLC_AYT = 6
SLC_EC = 7
