SLC_SUSP = 15
SLC_ABORT = 16

# SLC flags
SLC_ACK = 0x80
SLC_VALUE = 0x40
SLC_CANTCHANGE = 0x20
SLC_NOSUPPORT = 0x10
SLC_DEFAULT = 0x00

def send_telnet_command(sock, command):
    """Send a Telnet command to the socket"""
    sock.sendall(bytes([IAC, command]))

def send_linemode_slc(sock, func_code, flags, value):
    """Send a LINEMODE SLC subnegotiation"""
    # Construct the SLC subnegotiation
    # IAC SB LINEMODE SLC func_code flags value IAC SE
    msg = bytes([IAC, SB, LINEMODE, SLC, func_code, flags, value, IAC, SE])
    sock.sendall(msg)

